insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_architecture','architecture','noun','the art and work of designing buildings and planning how they are built','[{"senseId":"architecture_1","meaning":"the art and work of designing buildings and planning how they are built","acceptedParaphrases":["the design of buildings","the work of planning buildings"],"masteryContexts":[{"contextId":"u8_01_architecture_meaning","text":"The modern architecture of the new library, with its glass walls and open spaces, attracts many visitors.","meaning":"the style and design of a building","wrongMeanings":["the books and computers kept inside a building","the people who work inside a building","the rules about who may enter a building"]},{"contextId":"u8_01_architecture_paraphrase","text":"Before she could design hospitals, Lin spent six years studying architecture at university.","meaning":"the subject of designing buildings","wrongMeanings":["the subject of treating sick people","the subject of managing a business","the subject of making new medicines"]}],"situationDistractors":["A nurse checked the temperature of every patient on the ward.","A chef tasted a new sauce before the restaurant opened.","A shop assistant folded jumpers and put them on the shelves.","A driver delivered parcels to every house in the street.","A pilot checked the weather before the flight to Madrid.","A teacher marked a pile of history essays at the kitchen table."],"gapDistractors":[{"contextId":"u8_01_architecture_gap_1","answer":"architecture","wrong":["packaging","manufacturing","publicity"]},{"contextId":"u8_01_architecture_gap_2","answer":"architecture","wrong":["packaging","publicity","wellbeing"]},{"contextId":"u8_01_architecture_gap_3","answer":"architecture","wrong":["manufacturing","wellbeing","minority"]}],"spellingErrors":["architecure","archetecture","arcitecture","architechture","architecturre","arkitecture"],"wordFamilyForms":[{"form":"architecture","partOfSpeech":"noun","example":"She is interested in modern architecture and visits a new building every month.","pedagogicallyUseful":true},{"form":"architect","partOfSpeech":"noun","example":"The architect showed the clients a model of the new school.","pedagogicallyUseful":true,"altExample":"A young architect designed the new sports hall for the school."},{"form":"architectural","partOfSpeech":"adjective","example":"The old station has great architectural value, so it cannot be knocked down.","pedagogicallyUseful":true,"altExample":"The city is full of architectural styles from different centuries."}],"masteryPassages":[{"passageId":"u8_01_architecture_passage_1","contextId":"u8_01_architecture_gap_1","text":"Kemal spent his childhood drawing bridges, towers and houses. At university he chose to study ____, and now he designs schools for a living.","answer":"architecture"},{"passageId":"u8_01_architecture_passage_2","contextId":"u8_01_architecture_gap_2","text":"Tourists travel from all over the world to see the city’s ____. Its old palaces, glass towers and curved bridges are photographed every day.","answer":"architecture"}],"contextDependentParaphrases":[],"wrongParaphrases":["the repair of furniture","the sale of houses","the cleaning of offices"],"misleadingDistractors":["the work of repairing old furniture","the study of how cities are governed","the business of selling houses and flats"],"teacherNote":"Noun: the art, subject and profession of designing buildings; also the style of a building (modern architecture). Boundary: architecture is the work or the style; an architect is the person. The nouns architect and the adjective architectural are taught in the Word Family pathway."}]'::jsonb,'["architect","architectural"]'::jsonb,'["modern architecture","study architecture","a school of architecture"]'::jsonb,'live'),
('vocab_availability_8','availability','noun','the fact that something such as a material, product or job can be found and obtained','[{"senseId":"availability_8_1","meaning":"the fact that something such as a material, product or job can be found and obtained","acceptedParaphrases":["how easy something is to get","whether something can be obtained"],"masteryContexts":[{"contextId":"u8_02_availability_8_meaning","text":"The bakery changed its recipe because of the limited availability of good flour.","meaning":"whether a material can be obtained","wrongMeanings":["how much a material costs to buy","how a material is stored safely","how a material tastes when cooked"]},{"contextId":"u8_02_availability_8_paraphrase","text":"Young people often move to big cities because of the greater availability of jobs.","meaning":"how many jobs can be found","wrongMeanings":["how well jobs are paid","how hard jobs are to do","how long jobs usually last"]}],"situationDistractors":["A manager wrote a thank-you card to a worker who was leaving.","Two engineers argued about the colour of a new machine.","A trainer showed new staff where to hang their coats.","A director gave a short speech at the opening of a new office.","A cleaner polished the windows of the reception area.","A scientist wrote her results in a notebook."],"gapDistractors":[{"contextId":"u8_02_availability_8_gap_1","answer":"availability","wrong":["response","publicity","impact"]},{"contextId":"u8_02_availability_8_gap_2","answer":"availability","wrong":["packaging","manufacturing","architecture"]},{"contextId":"u8_02_availability_8_gap_3","answer":"availability","wrong":["humanity","architecture","minority"]}],"spellingErrors":["availablity","avalibility","availabilty","aviability","availibility","availabilaty"],"wordFamilyForms":[{"form":"availability","partOfSpeech":"noun","example":"The shop checks the availability of each item every morning.","pedagogicallyUseful":true},{"form":"available","partOfSpeech":"adjective","example":"Spare parts for this machine are no longer available in Europe.","pedagogicallyUseful":true,"altExample":"Is there a meeting room available on Tuesday afternoon?"},{"form":"unavailable","partOfSpeech":"adjective","example":"The manager was unavailable all morning because of a long meeting.","pedagogicallyUseful":true,"altExample":"The cheaper model is unavailable until next month."}],"masteryPassages":[{"passageId":"u8_02_availability_8_passage_1","contextId":"u8_02_availability_8_gap_1","text":"The restaurant wanted to serve fresh fish every day. However, the ____ of fish depends on the weather, because the boats cannot go out in storms.","answer":"availability"},{"passageId":"u8_02_availability_8_passage_2","contextId":"u8_02_availability_8_gap_2","text":"Before you choose a material for your design, check its ____. There is no point designing a chair in a wood that nobody can buy.","answer":"availability"}],"contextDependentParaphrases":[],"wrongParaphrases":["how much something costs","how good something tastes","how long something lasts"],"misleadingDistractors":["the price that customers must pay for something","the quality of the materials in a product","the number of people who want to buy something"],"teacherNote":"Noun: whether materials, products, jobs or services can be found and obtained (the availability of steel, the availability of jobs). Unit 8 keeps this supply sense for the world of work; Unit 7 taught the interview sense (when a person is free). The adjectives available and unavailable are taught in the Word Family pathway."}]'::jsonb,'["available","unavailable"]'::jsonb,'["the availability of materials","limited availability","check the availability of a product"]'::jsonb,'live'),
('vocab_concerned','concerned','adjective','worried about something that might be a problem','[{"senseId":"concerned_1","meaning":"worried about something that might be a problem","acceptedParaphrases":["worried","anxious about a problem"],"masteryContexts":[{"contextId":"u8_03_concerned_meaning","text":"Doctors are concerned about the number of office workers who sit all day without moving.","meaning":"worried about a possible problem","wrongMeanings":["pleased about a recent change","unsure about a simple fact","proud of a recent success"]},{"contextId":"u8_03_concerned_paraphrase","text":"Ana looked concerned when her manager asked to see her after the meeting.","meaning":"showing worry about what might happen","wrongMeanings":["showing joy about what had happened","showing anger about what had happened","showing boredom about what was happening"]}],"situationDistractors":["A worker smiled when she heard she had won an award.","A team laughed at a funny video during their lunch break.","A manager relaxed in the garden after a long week.","A trainer congratulated the new staff on passing their test.","A cashier counted the money and found that it was correct.","A director thanked everyone for a successful year."],"gapDistractors":[{"contextId":"u8_03_concerned_gap_1","answer":"concerned","wrong":["qualified","established","presented"]},{"contextId":"u8_03_concerned_gap_2","answer":"concerned","wrong":["transformed","launched","detailed"]},{"contextId":"u8_03_concerned_gap_3","answer":"concerned","wrong":["qualified","established","detailed"]}],"spellingErrors":["concernd","consurned","conserned","concerened","concernned","councerned"],"wordFamilyForms":[{"form":"concerned","partOfSpeech":"adjective","example":"The teacher was concerned about the student’s falling grades.","pedagogicallyUseful":true},{"form":"concern","partOfSpeech":"noun","example":"Safety is the main concern of everyone who works on the building site.","pedagogicallyUseful":true,"altExample":"Workers raised a concern about the broken fire door."},{"form":"unconcerned","partOfSpeech":"adjective","example":"He seemed completely unconcerned about the deadline, which annoyed his team.","pedagogicallyUseful":true,"altExample":"The manager was unconcerned by the small drop in sales."}],"masteryPassages":[{"passageId":"u8_03_concerned_passage_1","contextId":"u8_03_concerned_gap_1","text":"The doctor read the test results twice and frowned. She was ____ that the patient’s heart was beating too fast, so she asked for more tests.","answer":"concerned"},{"passageId":"u8_03_concerned_passage_2","contextId":"u8_03_concerned_gap_2","text":"Several neighbours wrote to the council. They were ____ about the noise and dust that the new factory would bring to the area.","answer":"concerned"}],"contextDependentParaphrases":[],"wrongParaphrases":["delighted","confused","bored"],"misleadingDistractors":["pleased that something has gone well","surprised by sudden news","bored by something that is repeated"],"teacherNote":"Adjective: worried, especially about a possible problem (concerned about, concerned that). Boundary: in \"the people concerned\" the word means involved, a different sense that is not taught here. The noun concern and the adjective unconcerned are taught in the Word Family pathway."}]'::jsonb,'["concern","unconcerned"]'::jsonb,'["concerned about","deeply concerned","concerned that something might happen"]'::jsonb,'live'),
('vocab_complicated','complicated','adjective','having many connected parts or steps, so it is difficult to understand or do','[{"senseId":"complicated_1","meaning":"having many connected parts or steps, so it is difficult to understand or do","acceptedParaphrases":["difficult to understand","full of confusing parts"],"masteryContexts":[{"contextId":"u8_04_complicated_meaning","text":"Building a car engine is a complicated job that needs hundreds of different parts.","meaning":"having many connected parts","wrongMeanings":["having very few moving parts","having a short and simple history","having a dangerous working area"]},{"contextId":"u8_04_complicated_paraphrase","text":"The tax form was so complicated that Lucy asked an expert to help her fill it in.","meaning":"hard to understand because of many details","wrongMeanings":["easy to read because it is short","boring to read because it repeats","costly to send because it is heavy"]}],"situationDistractors":["A child switched on the light by pressing one large button.","A worker opened a box by pulling a single strip of tape.","A customer paid for a coffee by tapping her phone once.","A driver turned left at the only crossroads in the village.","A new employee wrote her name on a badge.","An assistant put a letter in an envelope and posted it."],"gapDistractors":[{"contextId":"u8_04_complicated_gap_1","answer":"complicated","wrong":["qualified","concerned","launched"]},{"contextId":"u8_04_complicated_gap_2","answer":"complicated","wrong":["established","presented","qualified"]},{"contextId":"u8_04_complicated_gap_3","answer":"complicated","wrong":["curved","qualified","concerned"]}],"spellingErrors":["complecated","complicatted","compliceted","complicted","complacated","comlicated"],"wordFamilyForms":[{"form":"complicated","partOfSpeech":"adjective","example":"The new booking system is too complicated for most customers.","pedagogicallyUseful":true},{"form":"complicate","partOfSpeech":"verb","example":"Bad weather may complicate the delivery of the new machines.","pedagogicallyUseful":true,"altExample":"Adding more rules will only complicate the job."},{"form":"complication","partOfSpeech":"noun","example":"A small complication with the contract delayed the start of the project.","pedagogicallyUseful":true,"altExample":"The operation went well, without a single complication."}],"masteryPassages":[{"passageId":"u8_04_complicated_passage_1","contextId":"u8_04_complicated_gap_1","text":"Most people need a lesson before they can use the new software. It has dozens of menus and settings, and the instructions are long and ____.","answer":"complicated"},{"passageId":"u8_04_complicated_passage_2","contextId":"u8_04_complicated_gap_2","text":"Planning the wedding was more ____ than Sam expected. There were hundreds of guests, three different places to book and a menu that had to suit everyone.","answer":"complicated"}],"contextDependentParaphrases":[],"wrongParaphrases":["easy to repair","cheap to produce","quick to finish"],"misleadingDistractors":["very simple and quick to finish","old and no longer used","expensive to buy and to repair"],"teacherNote":"Adjective: with many parts or steps, so hard to understand or deal with. Boundary: complicated describes how many parts or steps something has; difficult can describe effort alone (a difficult climb is not complicated). The verb complicate and the noun complication are taught in the Word Family pathway."}]'::jsonb,'["complicate","complication"]'::jsonb,'["a complicated process","rather complicated","complicated instructions"]'::jsonb,'live'),
('vocab_curved','curved','adjective','having the shape of a smooth bend rather than a straight line','[{"senseId":"curved_1","meaning":"having the shape of a smooth bend rather than a straight line","acceptedParaphrases":["bent in a smooth line","rounded rather than straight"],"masteryContexts":[{"contextId":"u8_05_curved_meaning","text":"The road follows a curved path around the lake, so drivers must slow down.","meaning":"bending smoothly instead of going straight","wrongMeanings":["rising steeply up a hill","narrow with no room to pass","covered with loose stones"]},{"contextId":"u8_05_curved_paraphrase","text":"Zaha Hadid became famous for buildings with curved roofs that look like waves.","meaning":"shaped in smooth bends","wrongMeanings":["made of shiny glass panels","built very high above the ground","painted in bright colours"]}],"situationDistractors":["A carpenter cut a piece of wood into a perfect square.","A designer drew a straight line across the page with a ruler.","A builder made a wall with sharp corners at each end.","A worker stacked square boxes in neat rows.","An engineer measured a flat, straight beam of steel.","A painter marked a straight line down the middle of the road."],"gapDistractors":[{"contextId":"u8_05_curved_gap_1","answer":"curved","wrong":["qualified","concerned","launched"]},{"contextId":"u8_05_curved_gap_2","answer":"curved","wrong":["qualified","established","concerned"]},{"contextId":"u8_05_curved_gap_3","answer":"curved","wrong":["presented","qualified","launched"]}],"spellingErrors":["curvd","kerved","curvved","curveed","cerved","kurved"],"masteryPassages":[{"passageId":"u8_05_curved_passage_1","contextId":"u8_05_curved_gap_1","text":"The new chairs in the café are very comfortable. Their backs are ____, so they follow the shape of your spine when you lean back.","answer":"curved"},{"passageId":"u8_05_curved_passage_2","contextId":"u8_05_curved_gap_2","text":"From above, the bridge looks like a rainbow. Its ____ shape rises gently from one bank of the river and comes down on the other.","answer":"curved"}],"contextDependentParaphrases":[],"wrongParaphrases":["cut at a sharp angle","set in a straight row","broken into two pieces"],"misleadingDistractors":["having sharp corners and straight sides","very tall and narrow","broken into small pieces"],"teacherNote":"Adjective: shaped like a smooth bend, not straight (a curved roof, a curved line). Boundary: curved suggests a smooth, intended shape; bent can mean damaged out of shape. The only related form is curve (noun and verb), so no three-form family is taught."}]'::jsonb,'[]'::jsonb,'["a curved line","a curved roof","gently curved"]'::jsonb,'live'),
('vocab_detailed','detailed','adjective','giving many small facts or parts, not only the main points','[{"senseId":"detailed_1","meaning":"giving many small facts or parts, not only the main points","acceptedParaphrases":["full of small facts","giving every part carefully"],"masteryContexts":[{"contextId":"u8_06_detailed_meaning","text":"The architect made detailed drawings showing every window, door and light switch.","meaning":"showing many small parts","wrongMeanings":["showing only the outside shape","showing old and new styles","showing parts in bright colours"]},{"contextId":"u8_06_detailed_paraphrase","text":"The manager asked for a detailed explanation of why the delivery was late.","meaning":"giving all the facts and reasons","wrongMeanings":["giving a short, polite apology","giving a quick, spoken answer","giving a written promise to pay"]}],"situationDistractors":["A manager wrote \"Meeting at 3\" on a sticky note.","A worker gave a one-word answer when asked how her day was.","A customer left a review that said only \"Good\".","The director sent a two-line email to cancel the meeting.","A trainer gave the team a quick thumbs-up.","A colleague waved goodbye and left without a word."],"gapDistractors":[{"contextId":"u8_06_detailed_gap_1","answer":"detailed","wrong":["curved","concerned","qualified"]},{"contextId":"u8_06_detailed_gap_2","answer":"detailed","wrong":["concerned","qualified","launched"]},{"contextId":"u8_06_detailed_gap_3","answer":"detailed","wrong":["curved","concerned","qualified"]}],"spellingErrors":["detaled","detailled","deteiled","ditailed","detaild","deatailed"],"masteryPassages":[{"passageId":"u8_06_detailed_passage_1","contextId":"u8_06_detailed_gap_1","text":"The insurance company needs more than a short note. Please send a ____ report that lists every item that was damaged and how much it cost.","answer":"detailed"},{"passageId":"u8_06_detailed_passage_2","contextId":"u8_06_detailed_gap_2","text":"Before the builders began, the architect gave them ____ drawings. They showed the exact size of every room, window and door.","answer":"detailed"}],"contextDependentParaphrases":[],"wrongParaphrases":["full of strong opinions","short and very general","full of spelling mistakes"],"misleadingDistractors":["short and covering only the main idea","written quickly and carelessly","based on guesses rather than facts"],"teacherNote":"Adjective: containing many facts or small parts (a detailed report, detailed drawings). Boundary: detailed is about how much information is included; complicated is about how hard something is to understand. Detail (noun) is the only other common form, so no three-form family is taught."}]'::jsonb,'[]'::jsonb,'["a detailed report","detailed instructions","a detailed plan"]'::jsonb,'live'),
('vocab_development','development','noun','the process of creating a new product or idea and improving it over time','[{"senseId":"development_1","meaning":"the process of creating a new product or idea and improving it over time","acceptedParaphrases":["the creating of something new","the process of making and improving a product"],"masteryContexts":[{"contextId":"u8_07_development_meaning","text":"The company spends a lot of money on the development of new electric cars.","meaning":"creating and improving new products","wrongMeanings":["advertising products on television","repairing products that break","selling products in other countries"]},{"contextId":"u8_07_development_paraphrase","text":"Lena works in software development, writing and testing new apps for schools.","meaning":"the work of creating and improving programs","wrongMeanings":["the work of selling computers in shops","the work of fixing broken printers","the work of training office staff"]}],"situationDistractors":["A cashier gave a customer change at the end of the day.","A delivery driver unloaded boxes at the supermarket.","A cleaner emptied the bins in the office.","A receptionist answered the phone and took a message.","A security guard checked visitors’ badges at the door.","A waiter carried plates to a table by the window."],"gapDistractors":[{"contextId":"u8_07_development_gap_1","answer":"development","wrong":["publicity","packaging","minority"]},{"contextId":"u8_07_development_gap_2","answer":"development","wrong":["humanity","minority","architecture"]},{"contextId":"u8_07_development_gap_3","answer":"development","wrong":["wellbeing","packaging","employment"]}],"spellingErrors":["developement","devlopment","developmant","devolopment","developmeant","divelopment"],"wordFamilyForms":[{"form":"development","partOfSpeech":"noun","example":"The development of the new app took eighteen months.","pedagogicallyUseful":true},{"form":"develop","partOfSpeech":"verb","example":"The company plans to develop a cheaper electric car.","pedagogicallyUseful":true,"altExample":"Engineers are trying to develop a battery that lasts longer."},{"form":"developer","partOfSpeech":"noun","example":"Rosa works as a software developer for a games company.","pedagogicallyUseful":true,"altExample":"The developer fixed the problem in the app overnight."}],"masteryPassages":[{"passageId":"u8_07_development_passage_1","contextId":"u8_07_development_gap_1","text":"The team spent two years testing and improving their electric bike. Now that its ____ is complete, it will go on sale in the spring.","answer":"development"},{"passageId":"u8_07_development_passage_2","contextId":"u8_07_development_gap_2","text":"Creating a new medicine is slow and expensive. Its ____ often takes more than ten years of research and testing.","answer":"development"}],"contextDependentParaphrases":[],"wrongParaphrases":["the selling of something old","the cleaning of something used","the copying of something famous"],"misleadingDistractors":["the selling of a product to customers","the repairing of a broken product","the packing of products into boxes"],"teacherNote":"Noun: the work of creating something new and improving it (product development, the development of a drug). Boundary: development can also mean growth (child development) or new buildings on land; Unit 8 teaches the product and project sense. The verb develop and the noun developer are taught in the Word Family pathway."}]'::jsonb,'["develop","developer"]'::jsonb,'["product development","the development of new products","research and development"]'::jsonb,'live'),
('vocab_elements','elements','noun','the separate parts that together make up something','[{"senseId":"elements_1","meaning":"the separate parts that together make up something","acceptedParaphrases":["separate parts of a whole","different pieces that make something"],"masteryContexts":[{"contextId":"u8_08_elements_meaning","text":"A good advert has three elements: a clear picture, a short message and the company’s name.","meaning":"separate parts that together make a whole","wrongMeanings":["rules that tell people what to do","costs that a company must pay","people who have designed something"]},{"contextId":"u8_08_elements_paraphrase","text":"Customer service and teamwork are important elements of working in a hotel.","meaning":"parts that together make up a job","wrongMeanings":["people who manage a business","rooms that guests can use","prizes that are given to staff"]}],"situationDistractors":["A worker arrived ten minutes late for her shift.","A manager booked a taxi to the airport.","A cook burnt the toast and opened the window.","A director signed a letter and handed it back.","A builder took a break and drank some water.","A receptionist smiled at a visitor and said good morning."],"gapDistractors":[{"contextId":"u8_08_elements_gap_1","answer":"elements","wrong":["regulations","inspectors","facilities"]},{"contextId":"u8_08_elements_gap_2","answer":"elements","wrong":["inspectors","regulations","ingredients"]},{"contextId":"u8_08_elements_gap_3","answer":"elements","wrong":["inspectors","facilities","regulations"]}],"spellingErrors":["elemants","elemints","elemments","elaments","elementes","ellements"],"masteryPassages":[{"passageId":"u8_08_elements_passage_1","contextId":"u8_08_elements_gap_1","text":"A healthy meal usually has three ____: some protein, some vegetables and some grains. If one is missing, the meal is less balanced.","answer":"elements"},{"passageId":"u8_08_elements_passage_2","contextId":"u8_08_elements_gap_2","text":"The designer explained her poster to the class. She pointed to each of its ____ in turn: the photograph, the title and the bold red border.","answer":"elements"}],"contextDependentParaphrases":[],"wrongParaphrases":["official rules of a company","final costs of a project","main owners of a business"],"misleadingDistractors":["the rules that control how something is used","the materials that are left over after work","the people who are in charge of a project"],"teacherNote":"Plural noun: the separate parts that make up a whole (the elements of a design, key elements of a job). Boundary: in science, an element is a basic chemical substance such as oxygen; Unit 8 teaches the general \"part\" sense. No family is taught because elementary has moved away to mean basic."}]'::jsonb,'[]'::jsonb,'["key elements","the elements of a design","combine different elements"]'::jsonb,'live'),
('vocab_established','established','adjective','having existed for a long time and being accepted or respected','[{"senseId":"established_1","meaning":"having existed for a long time and being accepted or respected","acceptedParaphrases":["long-standing and respected","well known after many years"],"masteryContexts":[{"contextId":"u8_09_established_meaning","text":"Customers trust established brands more than new ones they have never heard of.","meaning":"existing for many years and trusted","wrongMeanings":["started only a few weeks ago","selling only cheap products","sold only in other countries"]},{"contextId":"u8_09_established_paraphrase","text":"After twenty years of work, she is now an established artist whose paintings sell around the world.","meaning":"recognised and respected after many years","wrongMeanings":["still studying and unknown to most people","retired and no longer painting","famous for one painting only"]}],"situationDistractors":["Two friends opened a new café last week.","A student set up an online shop from her bedroom yesterday.","A small company closed after only six months.","A new app appeared online this morning and has very few users.","A young designer is showing her work in public for the first time.","A man started a cleaning business with one bucket and a mop."],"gapDistractors":[{"contextId":"u8_09_established_gap_1","answer":"established","wrong":["curved","concerned","detailed"]},{"contextId":"u8_09_established_gap_2","answer":"established","wrong":["curved","concerned","presented"]},{"contextId":"u8_09_established_gap_3","answer":"established","wrong":["concerned","curved","launched"]}],"spellingErrors":["establised","estabished","establishd","esstablished","extablished","estableshed"],"wordFamilyForms":[{"form":"established","partOfSpeech":"adjective","example":"The museum works with established artists from many countries.","pedagogicallyUseful":true},{"form":"establish","partOfSpeech":"verb","example":"The two brothers hope to establish their own building company.","pedagogicallyUseful":true,"altExample":"The charity wants to establish a school in every village."},{"form":"establishment","partOfSpeech":"noun","example":"The hotel is a family establishment that has welcomed guests for decades.","pedagogicallyUseful":true,"altExample":"Smoking is not allowed in any establishment that serves food."}],"masteryPassages":[{"passageId":"u8_09_established_passage_1","contextId":"u8_09_established_gap_1","text":"The shoe shop on the high street has been run by the same family since 1890. It is one of the most ____ businesses in the town, and everyone knows its name.","answer":"established"},{"passageId":"u8_09_established_passage_2","contextId":"u8_09_established_gap_2","text":"Young writers often find it hard to get their books published. Publishers prefer ____ authors, who already have thousands of loyal readers.","answer":"established"}],"contextDependentParaphrases":[],"wrongParaphrases":["newly opened and unknown","small and badly run","cheap and poorly made"],"misleadingDistractors":["recently started and still unknown","closed down after a short time","owned and run by the government"],"teacherNote":"Adjective: having existed for a long time and being accepted (an established company, an established artist). Boundary: as a verb (established in 1920) it means started or set up; the adjective focuses on being long-standing. The verb establish and the noun establishment are taught in the Word Family pathway."}]'::jsonb,'["establish","establishment"]'::jsonb,'["an established company","well established","an established brand"]'::jsonb,'live'),
('vocab_facilities_8','facilities','noun','buildings, rooms, equipment or services provided for a particular purpose','[{"senseId":"facilities_8_1","meaning":"buildings, rooms, equipment or services provided for a particular purpose","acceptedParaphrases":["buildings and equipment for a purpose","places and services provided for people"],"masteryContexts":[{"contextId":"u8_10_facilities_8_meaning","text":"The hospital has modern facilities for treating patients with heart problems.","meaning":"equipment and rooms provided for a purpose","wrongMeanings":["doctors and nurses who work there","rules that patients must follow","records kept about each patient"]},{"contextId":"u8_10_facilities_8_paraphrase","text":"Workers at the factory complained that the washing facilities were dirty and broken.","meaning":"rooms and equipment for washing","wrongMeanings":["times set aside for washing","rules about washing hands","products used for washing"]}],"situationDistractors":["A manager told her team that the deadline had moved.","A worker phoned in sick on Monday morning.","An employee asked for a pay rise after two years.","Two colleagues disagreed about the best way to finish a report.","A trainer explained the company’s history to new staff.","A director chose a new logo for the company."],"gapDistractors":[{"contextId":"u8_10_facilities_8_gap_1","answer":"facilities","wrong":["inspectors","regulations","ingredients"]},{"contextId":"u8_10_facilities_8_gap_2","answer":"facilities","wrong":["regulations","inspectors","ingredients"]},{"contextId":"u8_10_facilities_8_gap_3","answer":"facilities","wrong":["inspectors","elements","regulations"]}],"spellingErrors":["facilitys","facilites","facillities","faciliteis","facilties","fasilities"],"masteryPassages":[{"passageId":"u8_10_facilities_8_passage_1","contextId":"u8_10_facilities_8_gap_1","text":"The new leisure centre is very popular. Its ____ include a swimming pool, a climbing wall and a café, and they are open until ten at night.","answer":"facilities"},{"passageId":"u8_10_facilities_8_passage_2","contextId":"u8_10_facilities_8_gap_2","text":"Before choosing a university, Amira visited the campus. She wanted to see the library, the laboratories and the other ____ that students could use.","answer":"facilities"}],"contextDependentParaphrases":[],"wrongParaphrases":["workers and managers of a company","rules and laws of a country","profits and costs of a business"],"misleadingDistractors":["the workers who run a business","the rules that visitors must follow","the money that a company earns"],"teacherNote":"Plural noun: buildings, rooms, equipment or services provided for a purpose (sports facilities, training facilities). Boundary: facilities are things people can use; they are not the workers or the rules of a place. No family is taught: facility in the singular often means a natural ability, and facilitate is a formal verb with a different meaning."}]'::jsonb,'[]'::jsonb,'["sports facilities","modern facilities","provide facilities"]'::jsonb,'live')
