('u8_idea_architecture',8,'idea_set','{"originalIdea":"The new library is famous for its bold architecture.","accurateParaphrases":["The new library is well known for the daring design of its building.","People know the new library because of its striking building design.","The building design of the new library is bold, and this has made it famous."],"meaningInvariants":[{"type":"meaning","value":"design of the building"}],"distractors":[{"text":"The new library is famous for its large collection of books.","misconceptionCategory":"meaning_confusion"},{"text":"The new library is unknown despite its bold design.","misconceptionCategory":"polarity_change"},{"text":"The new library will become famous for its bold design one day.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_architecture"],"primaryEvidenceTargetId":"vocab_architecture"}'::jsonb,'live'),
('u8_idea_availability',8,'idea_set','{"originalIdea":"The availability of skilled workers is the main reason the company chose this town.","accurateParaphrases":["The company picked this town mainly because skilled workers can easily be found there.","The main reason for choosing this town was that the firm could find skilled staff there.","Skilled workers are easy to find in this town, which is chiefly why the company chose it."],"meaningInvariants":[{"type":"cause_effect","value":"skilled workers can be found"}],"distractors":[{"text":"The low cost of skilled workers is the main reason the company chose this town.","misconceptionCategory":"meaning_confusion"},{"text":"The lack of skilled workers is the main reason the company chose this town.","misconceptionCategory":"polarity_change"},{"text":"Finding skilled workers was one small reason the company chose this town.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_availability_8"],"primaryEvidenceTargetId":"vocab_availability_8"}'::jsonb,'live'),
('u8_idea_concerned',8,'idea_set','{"originalIdea":"Many employees are concerned about losing their jobs to new technology.","accurateParaphrases":["A lot of workers are worried that new technology could take their jobs.","Many staff fear that they may lose their jobs because of new technology.","Plenty of employees feel anxious that new machines and software might replace them."],"meaningInvariants":[{"type":"meaning","value":"worried"}],"distractors":[{"text":"Many employees are excited about losing their jobs to new technology.","misconceptionCategory":"polarity_change"},{"text":"A few employees are worried about losing their jobs to new technology.","misconceptionCategory":"quantity_change"},{"text":"Many employees have already lost their jobs to new technology.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_concerned"],"primaryEvidenceTargetId":"vocab_concerned"}'::jsonb,'live'),
('u8_idea_complicated',8,'idea_set','{"originalIdea":"The instructions were so complicated that nobody could follow them.","accurateParaphrases":["The instructions were so hard to understand that no one was able to follow them.","Nobody could follow the instructions because they were too confusing.","Because the instructions had too many confusing details, no one managed to follow them."],"meaningInvariants":[{"type":"cause_effect","value":"too difficult to follow"}],"distractors":[{"text":"The instructions were so simple that everyone could follow them.","misconceptionCategory":"polarity_change"},{"text":"The instructions were rather confusing, but most people followed them.","misconceptionCategory":"degree_change"},{"text":"The instructions were so short that nobody read them.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_complicated"],"primaryEvidenceTargetId":"vocab_complicated"}'::jsonb,'live'),
('u8_idea_curved',8,'idea_set','{"originalIdea":"The building has curved walls instead of straight ones.","accurateParaphrases":["The walls of the building bend smoothly rather than running straight.","Instead of being straight, the building’s walls are rounded.","The building’s walls are not straight; they bend in smooth lines."],"meaningInvariants":[{"type":"meaning","value":"bending smoothly"}],"distractors":[{"text":"The building has straight walls instead of rounded ones.","misconceptionCategory":"polarity_change"},{"text":"The building has tall walls instead of short ones.","misconceptionCategory":"meaning_confusion"},{"text":"The building had curved walls before it was rebuilt.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_curved"],"primaryEvidenceTargetId":"vocab_curved"}'::jsonb,'live'),
('u8_idea_detailed',8,'idea_set','{"originalIdea":"The architect gave the builders detailed drawings of the new office.","accurateParaphrases":["The architect handed the builders drawings of the new office that showed every small part.","The builders received plans of the new office from the architect, with all the small parts shown.","Drawings of the new office showing every part carefully were given to the builders by the architect."],"meaningInvariants":[{"type":"meaning","value":"showing every small part"}],"distractors":[{"text":"The architect gave the builders rough drawings of the new office.","misconceptionCategory":"meaning_confusion"},{"text":"The builders gave the architect careful drawings of the new office.","misconceptionCategory":"role_reversal"},{"text":"The architect will give the builders full drawings of the new office.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_detailed"],"primaryEvidenceTargetId":"vocab_detailed"}'::jsonb,'live'),
('u8_idea_development',8,'idea_set','{"originalIdea":"The development of the new engine took four years.","accurateParaphrases":["Creating and improving the new engine took four years.","It took four years to design and perfect the new engine.","Four years were needed to create the new engine and make it work well."],"meaningInvariants":[{"type":"quantity","value":"four years"}],"distractors":[{"text":"The development of the new engine took four months.","misconceptionCategory":"quantity_change"},{"text":"The sale of the new engine took four years.","misconceptionCategory":"meaning_confusion"},{"text":"Creating the new engine will take four years.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_development"],"primaryEvidenceTargetId":"vocab_development"}'::jsonb,'live'),
('u8_idea_elements',8,'idea_set','{"originalIdea":"Colour and light are the most important elements of her design.","accurateParaphrases":["The most important parts of her design are colour and light.","In her design, colour and light are the key parts.","Of all the parts that make up her design, colour and light matter most."],"meaningInvariants":[{"type":"meaning","value":"most important parts"}],"distractors":[{"text":"Colour and light are the least important parts of her design.","misconceptionCategory":"polarity_change"},{"text":"Colour and light are the most expensive parts of her design.","misconceptionCategory":"meaning_confusion"},{"text":"Colour and light were once the most important parts of her design.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_elements"],"primaryEvidenceTargetId":"vocab_elements"}'::jsonb,'live'),
('u8_idea_established',8,'idea_set','{"originalIdea":"Most of our clients are established businesses rather than new ones.","accurateParaphrases":["Most of our customers are firms that have existed for many years, not new ones.","Long-standing businesses, rather than new firms, make up most of our client list.","The majority of our clients are well-known companies with a long history, not start-ups."],"meaningInvariants":[{"type":"quantity","value":"most"}],"distractors":[{"text":"Most of our clients are new businesses rather than long-standing ones.","misconceptionCategory":"polarity_change"},{"text":"Only a few of our clients are long-standing businesses.","misconceptionCategory":"quantity_change"},{"text":"Most of our clients are large businesses rather than small ones.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_established"],"primaryEvidenceTargetId":"vocab_established"}'::jsonb,'live'),
('u8_idea_facilities',8,'idea_set','{"originalIdea":"The factory has excellent facilities for its workers, including a canteen and a gym.","accurateParaphrases":["The factory provides its workers with very good places and equipment, such as a canteen and a gym.","Workers at the factory can use high-quality services, for example a canteen and a gym.","A canteen and a gym are among the very good things the factory provides for its staff."],"meaningInvariants":[{"type":"meaning","value":"places and equipment provided"}],"distractors":[{"text":"The factory has poor places and equipment for its workers, including a canteen and a gym.","misconceptionCategory":"polarity_change"},{"text":"The factory plans to build a canteen and a gym for its workers.","misconceptionCategory":"time_change"},{"text":"Only the managers can use the canteen and the gym at the factory.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_facilities_8"],"primaryEvidenceTargetId":"vocab_facilities_8"}'::jsonb,'live'),
('u8_idea_feature',8,'idea_set','{"originalIdea":"The main feature of the new office is a large garden on the roof.","accurateParaphrases":["The most noticeable part of the new office is a big rooftop garden.","A large garden on the roof is what stands out most about the new office.","What people notice most in the new office is the big garden on its roof."],"meaningInvariants":[{"type":"meaning","value":"most noticeable part"}],"distractors":[{"text":"The new office has no garden on the roof.","misconceptionCategory":"polarity_change"},{"text":"The main problem with the new office is a large garden on the roof.","misconceptionCategory":"meaning_confusion"},{"text":"The new office will have a large garden on the roof next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_feature_8"],"primaryEvidenceTargetId":"vocab_feature_8"}'::jsonb,'live'),
('u8_idea_humanity',8,'idea_set','{"originalIdea":"The new medicine could save millions of lives and benefit humanity.","accurateParaphrases":["The new drug might save millions of lives and help people all over the world.","Millions of lives could be saved by the new medicine, which would be good for the human race.","The new medicine may help everyone on the planet and save millions of lives."],"meaningInvariants":[{"type":"meaning","value":"all people"}],"distractors":[{"text":"The new medicine could save millions of lives but help only one country.","misconceptionCategory":"quantity_change"},{"text":"The new medicine could end millions of lives and harm everyone.","misconceptionCategory":"polarity_change"},{"text":"The new medicine has already saved millions of lives.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_humanity"],"primaryEvidenceTargetId":"vocab_humanity"}'::jsonb,'live'),
('u8_idea_impact',8,'idea_set','{"originalIdea":"The new factory has had a positive impact on the local economy.","accurateParaphrases":["The new factory has had a good effect on the local economy.","The local economy has benefited from the new factory.","Thanks to the new factory, the area’s economy has improved."],"meaningInvariants":[{"type":"meaning","value":"good effect"}],"distractors":[{"text":"The new factory has had a negative effect on the local economy.","misconceptionCategory":"polarity_change"},{"text":"The new factory will help the local economy in the future.","misconceptionCategory":"time_change"},{"text":"The new factory has made no difference to the local economy.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_impact"],"primaryEvidenceTargetId":"vocab_impact"}'::jsonb,'live'),
('u8_idea_ingredients',8,'idea_set','{"originalIdea":"The company uses only natural ingredients in its fruit juices.","accurateParaphrases":["The firm makes its fruit juices only from natural foods.","Nothing artificial goes into the company’s fruit juices.","The fruit juices are made entirely from natural things."],"meaningInvariants":[{"type":"quantity","value":"only natural"}],"distractors":[{"text":"The company uses mainly artificial foods in its fruit juices.","misconceptionCategory":"polarity_change"},{"text":"The company uses some natural foods in its fruit juices.","misconceptionCategory":"quantity_change"},{"text":"The company uses only natural packaging for its fruit juices.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_ingredients_8"],"primaryEvidenceTargetId":"vocab_ingredients_8"}'::jsonb,'live'),
('u8_idea_innovation',8,'idea_set','{"originalIdea":"The company encourages innovation by rewarding staff for new ideas.","accurateParaphrases":["The firm rewards its workers for fresh ideas in order to encourage new ways of working.","By giving rewards for new ideas, the company helps staff to create new things.","Staff who suggest new ideas are rewarded, because the company wants to develop new products and methods."],"meaningInvariants":[{"type":"cause_effect","value":"by rewarding new ideas"}],"distractors":[{"text":"The company discourages new ideas by punishing staff who suggest them.","misconceptionCategory":"polarity_change"},{"text":"The company encourages new ideas without rewarding anyone.","misconceptionCategory":"omitted_information"},{"text":"The company rewards staff for following old methods.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_innovation"],"primaryEvidenceTargetId":"vocab_innovation"}'::jsonb,'live'),
('u8_idea_inspiration',8,'idea_set','{"originalIdea":"The designer’s grandmother was the inspiration for her first collection.","accurateParaphrases":["The designer got the ideas for her first collection from her grandmother.","Her grandmother gave the designer the ideas behind her first collection.","The designer’s first collection was based on ideas that came from her grandmother."],"meaningInvariants":[{"type":"meaning","value":"source of ideas"}],"distractors":[{"text":"The designer’s grandmother paid for her first collection.","misconceptionCategory":"meaning_confusion"},{"text":"The designer gave her grandmother the ideas for her first collection.","misconceptionCategory":"role_reversal"},{"text":"The designer’s grandmother will give her ideas for her next collection.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_inspiration"],"primaryEvidenceTargetId":"vocab_inspiration"}'::jsonb,'live'),
('u8_idea_inspectors',8,'idea_set','{"originalIdea":"Inspectors visit every factory at least once a year to check safety.","accurateParaphrases":["Officials check safety in each factory one or more times a year.","Every factory receives a safety check from officials at least yearly.","At least once a year, each factory is visited by people who check that it is safe."],"meaningInvariants":[{"type":"quantity","value":"at least once a year"}],"distractors":[{"text":"Inspectors visit every factory once every ten years to check safety.","misconceptionCategory":"quantity_change"},{"text":"Inspectors visit only a few factories to check safety.","misconceptionCategory":"scope_change"},{"text":"Salespeople visit every factory at least once a year to sell products.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_inspectors"],"primaryEvidenceTargetId":"vocab_inspectors"}'::jsonb,'live'),
('u8_idea_instructor',8,'idea_set','{"originalIdea":"The instructor taught the new staff how to use the machines safely.","accurateParaphrases":["The new workers were shown how to operate the machines safely by the person teaching them.","The person in charge of teaching showed new employees how to use the machines without danger.","New staff learned safe use of the machines from their teacher."],"meaningInvariants":[{"type":"meaning","value":"person who teaches a skill"}],"distractors":[{"text":"The teacher showed the new staff how to repair the machines.","misconceptionCategory":"meaning_confusion"},{"text":"The new staff taught their teacher how to use the machines safely.","misconceptionCategory":"role_reversal"},{"text":"Nobody showed the new staff how to use the machines safely.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_instructor"],"primaryEvidenceTargetId":"vocab_instructor"}'::jsonb,'live'),
('u8_idea_launched',8,'idea_set','{"originalIdea":"The company launched its first electric car last year.","accurateParaphrases":["The firm started selling its first electric car last year.","Last year, the company introduced its first electric car to the public.","Its first electric car went on sale from the company last year."],"meaningInvariants":[{"type":"time","value":"last year"}],"distractors":[{"text":"The company will start selling its first electric car next year.","misconceptionCategory":"time_change"},{"text":"The company stopped making its first electric car last year.","misconceptionCategory":"polarity_change"},{"text":"The company bought its first electric car last year.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_launched"],"primaryEvidenceTargetId":"vocab_launched"}'::jsonb,'live'),
('u8_idea_landscape',8,'idea_set','{"originalIdea":"The new road has completely changed the landscape around the village.","accurateParaphrases":["The scenery around the village looks totally different because of the new road.","Because of the new road, the land around the village looks completely different.","The view of the countryside around the village has been entirely changed by the new road."],"meaningInvariants":[{"type":"degree","value":"completely"}],"distractors":[{"text":"The new road has slightly changed the scenery around the village.","misconceptionCategory":"degree_change"},{"text":"The new road has not changed the scenery around the village.","misconceptionCategory":"polarity_change"},{"text":"The new road has completely changed the traffic around the village.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_landscape_8"],"primaryEvidenceTargetId":"vocab_landscape_8"}'::jsonb,'live'),
('u8_idea_manufacturing',8,'idea_set','{"originalIdea":"Manufacturing has moved from Europe to Asia over the last thirty years.","accurateParaphrases":["Over the past thirty years, factory production has shifted from Europe to Asia.","In the last three decades, the making of goods in factories has moved from Europe to Asia.","Goods that used to be made in European factories have been produced in Asia over the last thirty years."],"meaningInvariants":[{"type":"direction","value":"from Europe to Asia"}],"distractors":[{"text":"Factory production has moved from Asia to Europe over the last thirty years.","misconceptionCategory":"direction_change"},{"text":"Shopping has moved from Europe to Asia over the last thirty years.","misconceptionCategory":"meaning_confusion"},{"text":"Factory production will move from Europe to Asia in the next thirty years.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_manufacturing"],"primaryEvidenceTargetId":"vocab_manufacturing"}'::jsonb,'live'),
('u8_idea_minority',8,'idea_set','{"originalIdea":"Only a minority of employees use the new gym.","accurateParaphrases":["Fewer than half of the workers use the new gym.","Most employees do not use the new gym; only a small number do.","The new gym is used by a smaller part of the staff."],"meaningInvariants":[{"type":"quantity","value":"fewer than half"}],"distractors":[{"text":"Most employees use the new gym.","misconceptionCategory":"quantity_change"},{"text":"No employees use the new gym.","misconceptionCategory":"polarity_change"},{"text":"Only a few employees like the new canteen.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_minority"],"primaryEvidenceTargetId":"vocab_minority"}'::jsonb,'live'),
('u8_idea_packaging',8,'idea_set','{"originalIdea":"The company has replaced all its plastic packaging with paper.","accurateParaphrases":["The firm now wraps all its products in paper instead of plastic.","Paper has taken the place of plastic in all of the company’s wrapping.","All of the company’s plastic boxes and wrappers have been changed to paper ones."],"meaningInvariants":[{"type":"quantity","value":"all"}],"distractors":[{"text":"The company has replaced some of its plastic wrapping with paper.","misconceptionCategory":"quantity_change"},{"text":"The company has replaced all its paper wrapping with plastic.","misconceptionCategory":"direction_change"},{"text":"The company plans to replace its plastic wrapping with paper.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_packaging"],"primaryEvidenceTargetId":"vocab_packaging"}'::jsonb,'live'),
('u8_idea_presented',8,'idea_set','{"originalIdea":"The engineer presented her design to the board last Friday.","accurateParaphrases":["Last Friday, the engineer showed and explained her design to the board.","The engineer formally showed the board her design last Friday.","Her design was explained to the board by the engineer last Friday."],"meaningInvariants":[{"type":"time","value":"last Friday"}],"distractors":[{"text":"The engineer will show her design to the board next Friday.","misconceptionCategory":"time_change"},{"text":"The board showed its design to the engineer last Friday.","misconceptionCategory":"role_reversal"},{"text":"The engineer hid her design from the board last Friday.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_presented"],"primaryEvidenceTargetId":"vocab_presented"}'::jsonb,'live'),
('u8_idea_publicity',8,'idea_set','{"originalIdea":"The company’s new advert has attracted a lot of publicity.","accurateParaphrases":["The firm’s new advert has received plenty of attention from the media and the public.","Many people and newspapers have noticed the company’s new advert.","The new advert from the company has been widely discussed in the media."],"meaningInvariants":[{"type":"quantity","value":"a lot of"}],"distractors":[{"text":"The company’s new advert has attracted very little attention.","misconceptionCategory":"quantity_change"},{"text":"The company’s new advert has attracted a lot of new staff.","misconceptionCategory":"meaning_confusion"},{"text":"The company’s new advert will attract a lot of attention next month.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_publicity"],"primaryEvidenceTargetId":"vocab_publicity"}'::jsonb,'live'),
('u8_idea_qualified',8,'idea_set','{"originalIdea":"Only qualified staff may use the machines in the laboratory.","accurateParaphrases":["Only workers with the right training are allowed to use the laboratory machines.","The machines in the laboratory can be used only by properly trained employees.","Staff without the official training must not use the laboratory machines."],"meaningInvariants":[{"type":"condition","value":"only trained staff"}],"distractors":[{"text":"Any member of staff may use the machines in the laboratory.","misconceptionCategory":"quantity_change"},{"text":"Only trained staff may clean the machines in the laboratory.","misconceptionCategory":"meaning_confusion"},{"text":"Only untrained staff may use the machines in the laboratory.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_qualified"],"primaryEvidenceTargetId":"vocab_qualified"}'::jsonb,'live'),
('u8_idea_regulations',8,'idea_set','{"originalIdea":"Under the new regulations, all drivers must take a break every four hours.","accurateParaphrases":["The new official rules say that every driver has to stop for a rest every four hours.","According to the new rules, drivers are required to take a break every four hours.","All drivers now have to rest every four hours because of the new rules."],"meaningInvariants":[{"type":"quantity","value":"every four hours"}],"distractors":[{"text":"Under the new rules, all drivers must take a break every eight hours.","misconceptionCategory":"quantity_change"},{"text":"Under the new rules, drivers may choose whether to take a break.","misconceptionCategory":"modality_change"},{"text":"Under the old rules, all drivers had to take a break every four hours.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_regulations"],"primaryEvidenceTargetId":"vocab_regulations"}'::jsonb,'live'),
('u8_idea_relentless',8,'idea_set','{"originalIdea":"The nurses face relentless demands during the winter months.","accurateParaphrases":["During winter, the nurses face demands that never stop.","In the winter months, there is constant pressure on the nurses.","The nurses have no break from heavy demands throughout the winter."],"meaningInvariants":[{"type":"degree","value":"never stopping"}],"distractors":[{"text":"The nurses face occasional demands during the winter months.","misconceptionCategory":"degree_change"},{"text":"The nurses face constant demands during the summer months.","misconceptionCategory":"time_change"},{"text":"The nurses make constant demands on their patients during the winter months.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_relentless"],"primaryEvidenceTargetId":"vocab_relentless"}'::jsonb,'live'),
('u8_idea_response',8,'idea_set','{"originalIdea":"The response to the new product has been very positive.","accurateParaphrases":["People have reacted very well to the new product.","The reaction to the new product has been extremely good.","Customers have given the new product a very positive reaction."],"meaningInvariants":[{"type":"meaning","value":"reaction"}],"distractors":[{"text":"The reaction to the new product has been very negative.","misconceptionCategory":"polarity_change"},{"text":"The price of the new product has been very low.","misconceptionCategory":"meaning_confusion"},{"text":"The reaction to the new product will probably be positive.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_response"],"primaryEvidenceTargetId":"vocab_response"}'::jsonb,'live'),
('u8_idea_responsible',8,'idea_set','{"originalIdea":"The supervisor is responsible for checking the machines every morning.","accurateParaphrases":["Checking the machines each morning is the supervisor’s job.","Every morning, it is the supervisor’s duty to check the machines.","The supervisor is in charge of inspecting the machines each morning."],"meaningInvariants":[{"type":"meaning","value":"duty"}],"distractors":[{"text":"The supervisor has to check the machines once a month.","misconceptionCategory":"quantity_change"},{"text":"The supervisor is not allowed to check the machines every morning.","misconceptionCategory":"polarity_change"},{"text":"The supervisor has to buy new machines every morning.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_responsible_8"],"primaryEvidenceTargetId":"vocab_responsible_8"}'::jsonb,'live'),
('u8_idea_rough',8,'idea_set','{"originalIdea":"The engineer gave us a rough estimate of the cost of the repairs.","accurateParaphrases":["The engineer told us approximately how much the repairs would cost.","We received a general idea of the repair costs from the engineer.","The engineer guessed about how much fixing it would cost, without exact figures."],"meaningInvariants":[{"type":"precision","value":"approximate"}],"distractors":[{"text":"The engineer gave us an exact price for the repairs.","misconceptionCategory":"precision_change"},{"text":"We gave the engineer an approximate idea of the cost of the repairs.","misconceptionCategory":"role_reversal"},{"text":"The engineer refused to say anything about the cost of the repairs.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_rough"],"primaryEvidenceTargetId":"vocab_rough"}'::jsonb,'live'),
('u8_idea_significant',8,'idea_set','{"originalIdea":"The new software has led to a significant fall in mistakes.","accurateParaphrases":["There are noticeably fewer mistakes because of the new software.","The new software has greatly reduced the number of mistakes.","Mistakes have dropped by a large amount since the new software arrived."],"meaningInvariants":[{"type":"degree","value":"large"}],"distractors":[{"text":"The new software has led to a small fall in mistakes.","misconceptionCategory":"degree_change"},{"text":"The new software has led to a large rise in mistakes.","misconceptionCategory":"direction_change"},{"text":"The new software will lead to a fall in mistakes next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_significant_8"],"primaryEvidenceTargetId":"vocab_significant_8"}'::jsonb,'live'),
('u8_idea_source',8,'idea_set','{"originalIdea":"Tourism is the island’s main source of jobs.","accurateParaphrases":["Most jobs on the island come from tourism.","The tourist industry provides more work than anything else on the island.","On the island, the largest number of jobs is created by tourism."],"meaningInvariants":[{"type":"quantity","value":"main"}],"distractors":[{"text":"Tourism provides only a few jobs on the island.","misconceptionCategory":"degree_change"},{"text":"Tourism has destroyed most jobs on the island.","misconceptionCategory":"polarity_change"},{"text":"Fishing provides most of the jobs on the island.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_source"],"primaryEvidenceTargetId":"vocab_source"}'::jsonb,'live'),
('u8_idea_specialise',8,'idea_set','{"originalIdea":"Our engineers specialise in designing bridges.","accurateParaphrases":["Our engineers focus on bridge design.","Designing bridges is the particular area that our engineers are experts in.","The particular field of our engineers is the design of bridges."],"meaningInvariants":[{"type":"meaning","value":"focus on one area"}],"distractors":[{"text":"Our engineers avoid designing bridges.","misconceptionCategory":"polarity_change"},{"text":"Our engineers design all kinds of buildings.","misconceptionCategory":"scope_change"},{"text":"Our engineers repair bridges.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_specialise_8"],"primaryEvidenceTargetId":"vocab_specialise_8"}'::jsonb,'live'),
('u8_idea_structures',8,'idea_set','{"originalIdea":"After the flood, engineers checked all the structures in the town.","accurateParaphrases":["After the flood, engineers examined every building and bridge in the town.","Every building, bridge and wall in the town was checked by engineers after the flood.","Engineers inspected everything that had been built in the town once the flood was over."],"meaningInvariants":[{"type":"quantity","value":"all"}],"distractors":[{"text":"After the flood, engineers checked a few buildings in the town.","misconceptionCategory":"quantity_change"},{"text":"Before the flood, engineers checked all the buildings in the town.","misconceptionCategory":"time_change"},{"text":"After the flood, engineers checked all the rivers in the town.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_structures"],"primaryEvidenceTargetId":"vocab_structures"}'::jsonb,'live'),
('u8_idea_sustainable',8,'idea_set','{"originalIdea":"The company wants all its products to be sustainable by 2030.","accurateParaphrases":["By 2030, the firm aims to make every product without harming the environment.","The company plans for all of its goods to be environmentally friendly by 2030.","By the year 2030, every product the company makes should be good for the planet in the long term."],"meaningInvariants":[{"type":"time","value":"by 2030"}],"distractors":[{"text":"The company wants some of its products to be environmentally friendly by 2030.","misconceptionCategory":"quantity_change"},{"text":"The company wants all its products to be cheaper by 2030.","misconceptionCategory":"meaning_confusion"},{"text":"The company wants all its products to be environmentally friendly by 2050.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_sustainable"],"primaryEvidenceTargetId":"vocab_sustainable"}'::jsonb,'live'),
('u8_idea_transformed',8,'idea_set','{"originalIdea":"Robots have transformed the way cars are made.","accurateParaphrases":["Robots have completely changed how cars are produced.","The method of making cars is totally different because of robots.","Car manufacturing has been changed in a major way by robots."],"meaningInvariants":[{"type":"degree","value":"completely"}],"distractors":[{"text":"Robots have slightly changed the way cars are made.","misconceptionCategory":"degree_change"},{"text":"Robots have not changed the way cars are made.","misconceptionCategory":"polarity_change"},{"text":"Robots have completely changed the way cars are sold.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_transformed"],"primaryEvidenceTargetId":"vocab_transformed"}'::jsonb,'live'),
('u8_idea_operator',8,'idea_set','{"originalIdea":"The operator must check the machine before every shift.","accurateParaphrases":["The person who works the machine has to inspect it before each shift.","Before every shift, the machine has to be checked by the worker who controls it.","Each shift, the person using the machine must check it first."],"meaningInvariants":[{"type":"time","value":"before every shift"}],"distractors":[{"text":"The person who works the machine must check it once a month.","misconceptionCategory":"quantity_change"},{"text":"The manager must check the machine before every shift.","misconceptionCategory":"role_change"},{"text":"The person who works the machine must clean it after every shift.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_operator"],"primaryEvidenceTargetId":"vocab_operator"}'::jsonb,'live'),
('u8_idea_nutritionist',8,'idea_set','{"originalIdea":"A nutritionist checks every new product before it goes on sale.","accurateParaphrases":["Each new product is checked by a food and health expert before it is sold.","Before any new product is sold, an expert on healthy eating examines it.","An expert in diet looks at every new product before it reaches the shops."],"meaningInvariants":[{"type":"time","value":"before it goes on sale"}],"distractors":[{"text":"A diet expert checks every new product after it goes on sale.","misconceptionCategory":"time_change"},{"text":"A diet expert checks a few new products before they go on sale.","misconceptionCategory":"quantity_change"},{"text":"A chef checks every new product before it goes on sale.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_nutritionist"],"primaryEvidenceTargetId":"vocab_nutritionist"}'::jsonb,'live'),
('u8_idea_director',8,'idea_set','{"originalIdea":"The director has decided to open a new office in Lagos.","accurateParaphrases":["The person in charge of the company has chosen to open a new office in Lagos.","A new office in Lagos will be opened, the head of the company has decided.","The company’s senior manager has made the decision to set up an office in Lagos."],"meaningInvariants":[{"type":"meaning","value":"person in charge"}],"distractors":[{"text":"The head of the company has decided to close the office in Lagos.","misconceptionCategory":"polarity_change"},{"text":"A trainee has decided to open a new office in Lagos.","misconceptionCategory":"role_change"},{"text":"The head of the company may open a new office in Lagos one day.","misconceptionCategory":"certainty_change"}],"linkedVocabularyIds":["vocab_director"],"primaryEvidenceTargetId":"vocab_director"}'::jsonb,'live'),
('u8_idea_expert',8,'idea_set','{"originalIdea":"The company asked an expert to check the safety of the new building.","accurateParaphrases":["The firm asked a specialist to make sure the new building was safe.","A person with special knowledge was asked by the company to examine how safe the new building was.","The company wanted someone highly skilled to inspect the safety of the new building."],"meaningInvariants":[{"type":"meaning","value":"person with special knowledge"}],"distractors":[{"text":"The company asked a beginner to check the safety of the new building.","misconceptionCategory":"meaning_confusion"},{"text":"The company asked a specialist to design the new building.","misconceptionCategory":"action_change"},{"text":"The company did not ask anyone to check the safety of the new building.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_expert"],"primaryEvidenceTargetId":"vocab_expert"}'::jsonb,'live'),
('u8_idea_engineer',8,'idea_set','{"originalIdea":"The engineer has designed a car that runs on hydrogen.","accurateParaphrases":["A car powered by hydrogen has been designed by the technical expert.","The person trained in designing machines has created a hydrogen-powered car.","A hydrogen car is the new design of the technical specialist."],"meaningInvariants":[{"type":"meaning","value":"person who designs machines"}],"distractors":[{"text":"The technical expert has bought a car that runs on hydrogen.","misconceptionCategory":"meaning_confusion"},{"text":"The technical expert will design a car that runs on hydrogen.","misconceptionCategory":"time_change"},{"text":"The technical expert has designed a car that runs on petrol.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_engineer_8"],"primaryEvidenceTargetId":"vocab_engineer_8"}'::jsonb,'live'),
('u8_idea_scientist',8,'idea_set','{"originalIdea":"A scientist at the university has discovered a new way to clean water.","accurateParaphrases":["A university researcher has found a new method of cleaning water.","A new method for making water clean has been found by a university researcher.","Someone who does research at the university has found a fresh way to purify water."],"meaningInvariants":[{"type":"meaning","value":"researcher"}],"distractors":[{"text":"A student at the university has bought a new machine to clean water.","misconceptionCategory":"meaning_confusion"},{"text":"A university researcher will try to discover a new way to clean water.","misconceptionCategory":"time_change"},{"text":"A university researcher has discovered a new way to pollute water.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_scientist"],"primaryEvidenceTargetId":"vocab_scientist"}'::jsonb,'live'),
('u8_idea_assignment',8,'idea_set','{"originalIdea":"All students must hand in their assignment by Friday.","accurateParaphrases":["Every student has to submit the set piece of work by Friday.","The task the students were given must be handed in by everyone by Friday.","By Friday, each student needs to give in their piece of set work."],"meaningInvariants":[{"type":"time","value":"by Friday"}],"distractors":[{"text":"All students must hand in their set work by next month.","misconceptionCategory":"time_change"},{"text":"Only some students must hand in their set work by Friday.","misconceptionCategory":"quantity_change"},{"text":"All students must collect their prize by Friday.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_assignment"],"primaryEvidenceTargetId":"vocab_assignment"}'::jsonb,'live'),
('u8_idea_employment',8,'idea_set','{"originalIdea":"The new factory will provide employment for five hundred people.","accurateParaphrases":["Five hundred people will get jobs at the new factory.","The new factory will give paid work to five hundred people.","Jobs for five hundred people will be created by the new factory."],"meaningInvariants":[{"type":"quantity","value":"five hundred"}],"distractors":[{"text":"The new factory will provide jobs for fifty people.","misconceptionCategory":"quantity_change"},{"text":"The new factory will provide training for five hundred people.","misconceptionCategory":"meaning_confusion"},{"text":"The new factory has stopped giving jobs to five hundred people.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_employment"],"primaryEvidenceTargetId":"vocab_employment"}'::jsonb,'live'),
('u8_idea_traditional',8,'idea_set','{"originalIdea":"The company still makes its cheese using traditional methods.","accurateParaphrases":["The firm continues to make its cheese in the way it has been made for centuries.","Long-established methods are still used by the company to produce its cheese.","The company has not changed the old way it makes its cheese."],"meaningInvariants":[{"type":"meaning","value":"long-established"}],"distractors":[{"text":"The company now makes its cheese using modern machines.","misconceptionCategory":"meaning_confusion"},{"text":"The company used to make its cheese using old methods.","misconceptionCategory":"time_change"},{"text":"The company makes its butter using old methods.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_traditional"],"primaryEvidenceTargetId":"vocab_traditional"}'::jsonb,'live'),
('u8_idea_trainer',8,'idea_set','{"originalIdea":"A trainer will teach all new staff how to use the software.","accurateParaphrases":["All new employees will be taught how to use the software by a person who trains staff.","Someone whose job is teaching skills will show every new worker how the software works.","Every new member of staff will learn the software from a coach."],"meaningInvariants":[{"type":"quantity","value":"all new staff"}],"distractors":[{"text":"A coach will teach some new staff how to use the software.","misconceptionCategory":"quantity_change"},{"text":"The new staff will teach a coach how to use the software.","misconceptionCategory":"role_reversal"},{"text":"A coach will teach all new staff how to repair the computers.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_trainer"],"primaryEvidenceTargetId":"vocab_trainer"}'::jsonb,'live'),
('u8_idea_technology',8,'idea_set','{"originalIdea":"Many factory jobs have disappeared because of new technology.","accurateParaphrases":["Lots of factory jobs no longer exist because of modern machines and computers.","Modern equipment has replaced many jobs in factories.","Because of new machines and computer systems, plenty of factory jobs have gone."],"meaningInvariants":[{"type":"cause_effect","value":"because of new machines"}],"distractors":[{"text":"Many factory jobs have been created because of new machines.","misconceptionCategory":"polarity_change"},{"text":"A few factory jobs have disappeared because of new machines.","misconceptionCategory":"quantity_change"},{"text":"Many factory jobs have disappeared because of high taxes.","misconceptionCategory":"cause_change"}],"linkedVocabularyIds":["vocab_technology"],"primaryEvidenceTargetId":"vocab_technology"}'::jsonb,'live'),
('u8_idea_creative',8,'idea_set','{"originalIdea":"The company is looking for creative designers to work on its new games.","accurateParaphrases":["The firm wants designers who are full of original ideas for its new games.","Imaginative designers are needed by the company for its new games.","The company needs designers who can think of new ideas to work on its next games."],"meaningInvariants":[{"type":"meaning","value":"imaginative"}],"distractors":[{"text":"The company is looking for careful testers to work on its new games.","misconceptionCategory":"meaning_confusion"},{"text":"The company is getting rid of imaginative designers.","misconceptionCategory":"polarity_change"},{"text":"The company was looking for imaginative designers last year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_creative"],"primaryEvidenceTargetId":"vocab_creative"}'::jsonb,'live'),
('u8_idea_wellbeing',8,'idea_set','{"originalIdea":"The company believes that staff wellbeing is more important than profit.","accurateParaphrases":["The firm thinks that the health and happiness of its workers matter more than making money.","According to the company, how well and happy employees feel is more important than earnings.","Making money matters less to the company than keeping its staff healthy and happy."],"meaningInvariants":[{"type":"comparison","value":"more important than profit"}],"distractors":[{"text":"The company believes that profit is more important than staff health and happiness.","misconceptionCategory":"comparison_reversal"},{"text":"The company believes that staff salaries are more important than profit.","misconceptionCategory":"meaning_confusion"},{"text":"The company once believed that staff health and happiness mattered more than profit.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_wellbeing"],"primaryEvidenceTargetId":"vocab_wellbeing"}'::jsonb,'live'),
('u8_writing_precision_architecture_a',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “the art of designing buildings” with a more precise Unit 8 word or phrase.","sourceText":"At sixteen, Marta decided that she wanted a career in the art of designing buildings.","acceptedAnswers":["architecture"],"distractors":["manufacturing","publicity","packaging"],"linkedVocabularyIds":["vocab_architecture"],"primaryEvidenceTargetId":"vocab_architecture"}'::jsonb,'live'),
('u8_writing_precision_architecture_b',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “style of the buildings” with a more precise Unit 8 word or phrase.","sourceText":"Many tourists come to Prague to photograph the style of the buildings in the old town.","acceptedAnswers":["architecture"],"distractors":["wellbeing","publicity","minority"],"linkedVocabularyIds":["vocab_architecture"],"primaryEvidenceTargetId":"vocab_architecture"}'::jsonb,'live'),
('u8_writing_precision_availability_a',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “chance of getting” with a more precise Unit 8 word or phrase.","sourceText":"The chance of getting fresh fish is lower in winter because the boats stay in port.","acceptedAnswers":["availability"],"distractors":["packaging","publicity","impact"],"linkedVocabularyIds":["vocab_availability_8"],"primaryEvidenceTargetId":"vocab_availability_8"}'::jsonb,'live'),
('u8_writing_precision_availability_b',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “ease of finding” with a more precise Unit 8 word or phrase.","sourceText":"Students compared the ease of finding part-time jobs in different towns.","acceptedAnswers":["availability"],"distractors":["publicity","impact","development"],"linkedVocabularyIds":["vocab_availability_8"],"primaryEvidenceTargetId":"vocab_availability_8"}'::jsonb,'live'),
('u8_writing_precision_concerned_a',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “a bit worried” with a more precise Unit 8 word or phrase.","sourceText":"The head teacher was a bit worried that the school trip would be cancelled because of the snow.","acceptedAnswers":["concerned"],"distractors":["delighted","certain","relieved"],"linkedVocabularyIds":["vocab_concerned"],"primaryEvidenceTargetId":"vocab_concerned"}'::jsonb,'live'),
('u8_writing_precision_concerned_b',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “nervous” with a more precise Unit 8 word or phrase.","sourceText":"Residents felt nervous about the plan to build a chemical factory near the river.","acceptedAnswers":["concerned"],"distractors":["excited","curious","proud"],"linkedVocabularyIds":["vocab_concerned"],"primaryEvidenceTargetId":"vocab_concerned"}'::jsonb,'live'),
('u8_writing_precision_complicated_a',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “hard to understand” with a more precise Unit 8 word or phrase.","sourceText":"Many customers think the new phone contract is hard to understand and full of small print.","acceptedAnswers":["complicated"],"distractors":["traditional","sustainable","creative"],"linkedVocabularyIds":["vocab_complicated"],"primaryEvidenceTargetId":"vocab_complicated"}'::jsonb,'live'),
('u8_writing_precision_complicated_b',8,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “full of difficult steps” with a more precise Unit 8 word or phrase.","sourceText":"The process for opening a bank account was full of difficult steps, so it took Mia three days.","acceptedAnswers":["complicated"],"distractors":["traditional","creative","sustainable"],"linkedVocabularyIds":["vocab_complicated"],"primaryEvidenceTargetId":"vocab_complicated"}'::jsonb,'live'),
